# Data for duplicated ACTIVITY_INSTANCE_CLASS relationships.
# Query:
# MATCH (av:ActivityInstanceValue)-[raic:ACTIVITY_INSTANCE_CLASS]->(aicr:ActivityInstanceClassRoot)
# WITH av, aicr, collect(raic) as rels
# WHERE size(rels) > 1
# WITH collect(DISTINCT av) + collect(DISTINCT aicr) AS importNodes, rels AS importRels
# CALL apoc.export.cypher.data(importNodes, importRels,
#   NULL,
#   { format: "plain", cypherFormat: "create", stream: true})
# YIELD cypherStatements, file, batches, source, format, nodes, relationships, time, rows, batchSize
# RETURN cypherStatements
DUPLICATED_INSTANCE_CLASS_RELS = """
CREATE RANGE INDEX IF NOT EXISTS FOR (n:ActivityInstanceValue) ON (n.name);
CREATE RANGE INDEX IF NOT EXISTS FOR (n:ConceptValue) ON (n.name);
CREATE RANGE INDEX IF NOT EXISTS FOR (n:TemplateParameterTermValue) ON (n.name);
CREATE CONSTRAINT constraint_ActivityInstanceClassRoot_uid IF NOT EXISTS FOR (node:ActivityInstanceClassRoot) REQUIRE (node.uid) IS NODE KEY;
CREATE CONSTRAINT UNIQUE_IMPORT_NAME IF NOT EXISTS FOR (node:`UNIQUE IMPORT LABEL`) REQUIRE (node.`UNIQUE IMPORT ID`) IS UNIQUE;
UNWIND [{_id:859115, properties:{topic_code:"END_OF_TREATMENT", is_derived:false, adam_param_code:"EOTREAT", name:"End of Treatment", name_sentence_case:"end of treatment", is_default_selected_for_activity:false, is_data_sharing:false, legacy_description:"End of Treatment", is_required_for_activity:false, is_legacy_usage:false}}] AS row
CREATE (n:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row._id}) SET n += row.properties SET n:ConceptValue:ActivityInstanceValue:TemplateParameterTermValue;
UNWIND [{uid:"ActivityInstanceClass_000005", properties:{}}] AS row
CREATE (n:ActivityInstanceClassRoot{uid: row.uid}) SET n += row.properties;
UNWIND [{start: {_id:859115}, end: {uid:"ActivityInstanceClass_000005"}, properties:{`UNIQUE IMPORT ID REL`:6814948}}, {start: {_id:859115}, end: {uid:"ActivityInstanceClass_000005"}, properties:{`UNIQUE IMPORT ID REL`:2178426}}] AS row
MATCH (start:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row.start._id})
MATCH (end:ActivityInstanceClassRoot{uid: row.end.uid})
CREATE (start)-[r:ACTIVITY_INSTANCE_CLASS]->(end) SET r += row.properties;
MATCH (n:`UNIQUE IMPORT LABEL`)  WITH n LIMIT 20000 REMOVE n:`UNIQUE IMPORT LABEL` REMOVE n.`UNIQUE IMPORT ID`;
DROP CONSTRAINT UNIQUE_IMPORT_NAME;
"""


